using System.Globalization;using System.Windows; namespace AutoPecasERP.Desktop.Views; public partial class ValorDialog:Window{public decimal Valor{get;private set;}public string Observacao=>ObsBox.Text;public ValorDialog(string titulo):this(titulo,0){}public ValorDialog(string titulo,decimal inicial){InitializeComponent();Titulo.Text=titulo;ValorBox.Text=inicial.ToString("N2",CultureInfo.GetCultureInfo("pt-BR"));}void Ok_Click(object s,RoutedEventArgs e){var t=ValorBox.Text.Replace("R$","").Trim();if((!decimal.TryParse(t,NumberStyles.Number,CultureInfo.GetCultureInfo("pt-BR"),out var v)&&!decimal.TryParse(t,out v))||v<0){MessageBox.Show("Informe um valor válido.");return;}Valor=v;DialogResult=true;}}